    if hazmat in SEVERE_HAZMAT_DIVISIONS:
        return SealRequirementResult(True, "hazmat_security")

    if commodity in AUTO_SEAL_COMMODITIES:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "commodity_sensitive")
        return SealRequirementResult(False, "equipment_not_sealable")

    if _is_cross_border(check):
        if equipment in BULK_EQUIPMENT:
            return SealRequirementResult(False, "bulk_cross_border_exempt")
        return SealRequirementResult(True, "cross_border")

    if check.ctpat_member or check.bonded_shipment:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "security_program")
        return SealRequirementResult(False, "equipment_not_sealable")

    if commodity == "produce":
        if check.weight_lb >= PRODUCE_WEIGHT_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "produce_food_safety")
        return SealRequirementResult(False, "produce_below_threshold")

    if customer == "hartline retail":
        pallets = check.pallet_count.quantize(Decimal("0.1"))
        if check.is_return and pallets < HARTLINE_RETURN_EXEMPT_THRESHOLD:
            return SealRequirementResult(False, "customer_return_exempt")
        if pallets > HARTLINE_PALLET_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "customer_policy")
        return SealRequirementResult(False, "customer_below_threshold")

    return SealRequirementResult(False, "not_required")

hazmat.py:
"""Hazmat handling on truckload and LTL loads.

Two separate questions are answered here. ``requires_placards`` says whether the
truck must display hazmat placards, which dispatch uses to pick a driver with the
hazmat endorsement: a load needs placards at 1,001 lb or more aggregate hazmat
weight, or for any amount of a Table 1 material. ``hazmat_surcharge`` is what the
customer pays for hazmat on the load, which settlement adds as an accessorial.
"""

from dataclasses import dataclass
from decimal import Decimal

HAZMAT_SURCHARGE = Decimal("150.00")
PLACARD_THRESHOLD_LB = Decimal("1001")
# Hazard classes placarded at any quantity (49 CFR 172.504 Table 1, simplified).
TABLE_1_CLASSES = frozenset({"1.1", "1.2", "1.3", "2.3", "4.3", "6.1-PIH", "7"})


@dataclass(frozen=True)
class FreightLine:
    description: str
    weight_lb: Decimal
    un_number: str | None = None
    hazard_class: str | None = None

    @property
    def is_hazmat(self) -> bool:
        return self.un_number is not None


@dataclass(frozen=True)
class Load:
    load_id: str
    customer: str
    lines: tuple[FreightLine, ...]


def hazmat_weight(load: Load) -> Decimal:
    return sum((line.weight_lb for line in load.lines if line.is_hazmat), Decimal("0"))


def requires_placards(load: Load) -> bool:
    if any(line.is_hazmat and line.hazard_class in TABLE_1_CLASSES for line in load.lines):
        return True
    return hazmat_weight(load) >= PLACARD_THRESHOLD_LB


def hazmat_surcharge(load: Load) -> Decimal:
    """The hazmat accessorial: a flat charge for any hazmat on the load."""
    if any(line.is_hazmat for line in load.lines):
        return HAZMAT_SURCHARGE
    return Decimal("0.00")

inside_delivery_fee.py:
"""Inside-delivery accessorials for shipments moved beyond the receiver's dock.

Inside delivery is billed when the consignee asks the driver to place freight inside a
building rather than leaving it at the dock or curb. Tidewater's standard rules are:

- Base fee depends on service level: threshold, room-of-choice, and white glove.
- Service includes one floor at no extra charge.
- Additional floors are billed per floor, but elevator stops reduce the per-floor charge.
- No floor surcharge applies when the destination floor is 1 or lower.
- Piece-heavy deliveries add a handling surcharge above a service-specific included count.
- White glove includes more pieces before the surcharge begins.
- Threshold deliveries with 25 or more pieces add a flat heavy-handling bump.
- The final fee is the greater of the computed amount and the contract minimum charge.
- All money is rounded half up to the nearest cent after surcharges are added.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

BASE_BY_SERVICE = {
    "threshold": Decimal("45.00"),
    "room_of_choice": Decimal("85.00"),
    "white_glove": Decimal("140.00"),
}

EXTRA_FLOOR_RATE = {
    "threshold": Decimal("18.00"),
    "room_of_choice": Decimal("25.00"),
    "white_glove": Decimal("35.00"),
}

ELEVATOR_EXTRA_FLOOR_RATE = {
    "threshold": Decimal("10.00"),
    "room_of_choice": Decimal("14.00"),
    "white_glove": Decimal("20.00"),
}

INCLUDED_PIECES = {
    "threshold": 5,
    "room_of_choice": 10,
    "white_glove": 15,
}

PER_PIECE_SURCHARGE = Decimal("3.50")
THRESHOLD_HEAVY_HANDLING_BUMP = Decimal("10.50")
DEFAULT_MINIMUM_CHARGE = Decimal("55.00")


@dataclass(frozen=True)
class InsideDeliveryRequest:
    service_level: str
    floor_count: int
    has_elevator: bool
    piece_count: int


@dataclass(frozen=True)
class InsideDeliveryTerms:
    minimum_charge: Decimal = DEFAULT_MINIMUM_CHARGE


def _validate(request: InsideDeliveryRequest, terms: InsideDeliveryTerms) -> None:
    if request.service_level not in BASE_BY_SERVICE:
        raise ValueError(f"unknown service level: {request.service_level}")
    if request.floor_count < 0:
        raise ValueError(f"floor_count must be >= 0, got {request.floor_count}")
    if request.piece_count < 0:
        raise ValueError(f"piece_count must be >= 0, got {request.piece_count}")
    if terms.minimum_charge < Decimal("0.00"):
        raise ValueError(f"minimum_charge must be >= 0.00, got {terms.minimum_charge}")


def _extra_floors(floor_count: int) -> int:
    return max(0, floor_count - 1)


def _floor_surcharge(request: InsideDeliveryRequest) -> Decimal:
    floors = _extra_floors(request.floor_count)
    if floors == 0:
        return Decimal("0.00")
    rates = ELEVATOR_EXTRA_FLOOR_RATE if request.has_elevator else EXTRA_FLOOR_RATE
    return rates[request.service_level] * floors


def _piece_surcharge(request: InsideDeliveryRequest) -> Decimal:
    included = INCLUDED_PIECES[request.service_level]
    extra_pieces = max(0, request.piece_count - included)
    if extra_pieces == 0:
        return Decimal("0.00")
    surcharge = PER_PIECE_SURCHARGE * extra_pieces
    if request.service_level == "threshold" and request.piece_count >= 25:
        surcharge += THRESHOLD_HEAVY_HANDLING_BUMP
    return surcharge


def _rounded(amount: Decimal) -> Decimal:
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def calculate_inside_delivery_fee(
    request: InsideDeliveryRequest,
    terms: InsideDeliveryTerms = InsideDeliveryTerms(),
) -> Decimal:
    """Inside-delivery fee for one stop, in dollars.

    The fee is base service price plus floor and piece surcharges. One floor is included.
    Elevator buildings use a lower extra-floor rate. The final amount is rounded to cents,
    then raised to ``terms.minimum_charge`` if needed.
    """
    _validate(request, terms)
    amount = BASE_BY_SERVICE[request.service_level]
    amount += _floor_surcharge(request)
    amount += _piece_surcharge(request)
    amount = _rounded(amount)
    if amount < terms.minimum_charge:
        return _rounded(terms.minimum_charge)
    return amount

lane_rates.py:
"""Contract lane rate lookup with fallbacks.

Customer contracts price linehaul per mile by lane. Pricing loads them at three
levels of detail, most specific first:

    zip3        origin ZIP3 -> destination ZIP3   ("972" -> "837")
    zip3_state  origin ZIP3 -> destination state  ("972" -> "ID")
    state       origin state -> destination state ("OR" -> "ID")

Every rate has an effective date and an optional expiry date (inclusive). Rates
get renegotiated lane by lane, so the specific lanes often lapse before the
state-level rates do. A lookup uses the most specific level that has a rate in
effect on the ship date, and falls back to the customer's default per-mile rate
when no level does. If two rates at one level are in effect at once, the one with
the later effective date wins: it is the newer contract amendment.
"""

from dataclasses import dataclass
from datetime import date
from decimal import ROUND_HALF_UP, Decimal

LEVELS = ("zip3", "zip3_state", "state")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class LaneRate:
    level: str
    origin: str
    dest: str
    rate_per_mile: Decimal
    effective: date
    expires: date | None = None


@dataclass(frozen=True)
class Shipment:
    origin_zip: str
    origin_state: str
    dest_zip: str
    dest_state: str
    ship_date: date


@dataclass(frozen=True)
class RateMatch:
    rate_per_mile: Decimal
    level: str


RateTable = dict[tuple[str, str, str], list[LaneRate]]


def build_rate_table(rates: list[LaneRate]) -> RateTable:
    table: RateTable = {}
    for rate in rates:
        if rate.level not in LEVELS:
            raise ValueError(f"unknown lane level {rate.level!r}")
        table.setdefault((rate.level, rate.origin, rate.dest), []).append(rate)
    return table


def _candidate_keys(shipment: Shipment) -> list[tuple[str, str, str]]:
    origin3, dest3 = shipment.origin_zip[:3], shipment.dest_zip[:3]
    return [
        ("zip3", origin3, dest3),
        ("zip3_state", origin3, shipment.dest_state),
        ("state", shipment.origin_state, shipment.dest_state),
    ]


def _in_effect(rates: list[LaneRate], on: date) -> list[LaneRate]:
    return [r for r in rates if r.effective <= on and (r.expires is None or on <= r.expires)]


def _most_specific(table: RateTable, shipment: Shipment) -> tuple[str | None, list[LaneRate]]:
    """The most specific level with a rate in effect for this lane, and those rates.

    A level whose only rates have expired (or are not yet effective) is skipped so
    the lookup can fall through to the next, less specific level.
    """
    for key in _candidate_keys(shipment):
        if key in table:
            live = _in_effect(table[key], shipment.ship_date)
            if live:
                return key[0], live
    return None, []


def lookup_lane_rate(
    table: RateTable, shipment: Shipment, default_rate: Decimal | None = None
) -> RateMatch:
    """The per-mile rate for ``shipment``, and which level it came from.

    Raises LookupError if no lane rate applies and the customer has no default.
    """
    level, live = _most_specific(table, shipment)
    if live:
        newest = max(live, key=lambda rate: rate.effective)
        return RateMatch(newest.rate_per_mile, level)
    if default_rate is None:
        raise LookupError(f"no lane rate for {shipment.origin_zip} -> {shipment.dest_zip}")
    return RateMatch(default_rate, "default")


def linehaul(table: RateTable, shipment: Shipment, miles: Decimal, default_rate: Decimal | None = None) -> Decimal:
    """Linehaul dollars for the shipment's miles, rounded to the cent."""
    rate = lookup_lane_rate(table, shipment, default_rate).rate_per_mile
    return (rate * miles).quantize(CENT, rounding=ROUND_HALF_UP)

payment_terms_due_date.py:
"""Invoice payment terms due dates for carrier settlements and customer billing.

The billing platform uses one rules engine for customer invoices and carrier self-bills.
This module computes the contractual due date from an issue date plus term details.
Standard net terms add calendar days to the issue date. Some contracts use end-of-
month handling: if issued on or after a threshold day, the due date is based on the
last day of the following month instead of simple day addition. After the base date is
chosen, non-business-day rolling applies. Weekend and listed holiday dates can roll
forward to the next business day or backward to the previous business day; a contract
may also specify no rolling. A grace period may then be added in business days.
"""

from dataclasses import dataclass, field
from datetime import date, timedelta


@dataclass(frozen=True)
class PaymentTermsInput:
    issue_date: date
    terms_days: int
    eom_threshold_day: int | None = None
    roll_rule: str = "forward"
    holiday_dates: frozenset[date] = field(default_factory=frozenset)
    grace_business_days: int = 0


_VALID_ROLL_RULES = {"forward", "backward", "none"}


def _validate(terms: PaymentTermsInput) -> None:
    if terms.terms_days < 0:
        raise ValueError("terms_days must be >= 0")
    if terms.grace_business_days < 0:
        raise ValueError("grace_business_days must be >= 0")
    if terms.roll_rule not in _VALID_ROLL_RULES:
        raise ValueError(f"unsupported roll_rule {terms.roll_rule!r}")
    if terms.eom_threshold_day is not None and not 1 <= terms.eom_threshold_day <= 31:
        raise ValueError("eom_threshold_day must be between 1 and 31")


def _last_day_of_month(day: date) -> date:
    if day.month == 12:
        return date(day.year, 12, 31)
    return date(day.year, day.month + 1, 1) - timedelta(days=1)


def _is_business_day(day: date, holidays: frozenset[date]) -> bool:
    return day.weekday() < 5 and day not in holidays


def _roll(day: date, rule: str, holidays: frozenset[date]) -> date:
    if rule == "none" or _is_business_day(day, holidays):
        return day
    step = 1 if rule == "forward" else -1
    current = day
    while not _is_business_day(current, holidays):
        current += timedelta(days=step)
    return current


def _add_business_days(day: date, business_days: int, holidays: frozenset[date]) -> date:
    current = day
    added = 0
    while added < business_days:
        current += timedelta(days=1)
        if _is_business_day(current, holidays):
            added += 1
    return current


def _base_due_date(terms: PaymentTermsInput) -> date:
    if terms.eom_threshold_day is None or terms.issue_date.day < terms.eom_threshold_day:
        return terms.issue_date + timedelta(days=terms.terms_days)

    issue = terms.issue_date
    if issue.month == 12:
        first_of_next_month = date(issue.year + 1, 1, 1)
    else:
        first_of_next_month = date(issue.year, issue.month + 1, 1)
    return _last_day_of_month(first_of_next_month) + timedelta(days=terms.terms_days)


def calculate_payment_terms_due_date(terms: PaymentTermsInput) -> date:
    """Return the contractual due date after EOM logic, rolling, and grace days.

    EOM logic applies only when ``eom_threshold_day`` is set and the issue day is on
    or after the threshold. In that case, the base date is the last day of the next
    month plus ``terms_days``. The base date is then rolled per ``roll_rule`` if it
    lands on a weekend or listed holiday. Finally, ``grace_business_days`` are added
    as business days.

    >>> calculate_payment_terms_due_date(PaymentTermsInput(issue_date=date(2026, 1, 10), terms_days=30))
    datetime.date(2026, 2, 9)
    """
    _validate(terms)
    base = _base_due_date(terms)
    if terms.grace_business_days == 0 and terms.terms_days == 0:
        return base
    rolled = _roll(base, terms.roll_rule, terms.holiday_dates)
    return _add_business_days(rolled, terms.grace_business_days, terms.holiday_dates)

edi_unit_normalization.py:
"""Normalize EDI quantities into Tidewater's canonical internal units.

Inbound EDI feeds use several unit codes for weights and dimensions. Billing,
planning, and rating want a single canonical unit per measure, but partners do
not always follow the same conventions across transactions. The rules below are
used during ingest:

- Weight canonical unit is pounds (LB). Kilograms convert at 2.20462 lb/kg.
- Dimension canonical unit is inches (IN). Feet convert at 12 in/ft; meters
  convert at 39.3701 in/m; centimeters convert at 0.393701 in/cm.
- Piece-like counts (EA, CT, PLT) remain counts and are rounded to whole units.
- Transaction-specific overrides apply before conversion. On shipment-status
  transactions (214), partner code ``M`` means minutes, not meters, so it is not
  normalized here. On invoice transactions (210), code ``PC`` means pieces.
- Very small positive weights under 1 lb round up to 1 lb because linehaul and
  accessorial rating do not allow a zero actual weight. Weight over 48,000 lb is
  rejected as an implausible single-line shipment value.
- Dimensions are rounded to the nearest whole inch, except values under 1 inch
  but above zero round up to 1 inch. Dimensions over 1,080 inches are rejected.
- Counts are rounded half up to whole units, but any positive count below 1
  becomes 1. Negative quantities and unknown codes are rejected.
"""

from dataclasses import dataclass
from decimal import ROUND_CEILING, ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
KG_TO_LB = Decimal("2.20462")
M_TO_IN = Decimal("39.3701")
CM_TO_IN = Decimal("0.393701")
FT_TO_IN = Decimal("12")
MAX_WEIGHT_LB = Decimal("48000")
MAX_DIMENSION_IN = Decimal("1080")


@dataclass(frozen=True)
class EDIQuantity:
    quantity: Decimal
    unit_code: str
    transaction_set: str
    partner_id: str | None = None


@dataclass(frozen=True)
class NormalizedUnits:
    quantity: Decimal
    canonical_unit: str


def _clean_code(unit_code: str) -> str:
    code = unit_code.strip().upper()
    if not code:
        raise ValueError("unit_code is blank")
    return code


def _effective_code(item: EDIQuantity) -> str:
    code = _clean_code(item.unit_code)
    tx = item.transaction_set.strip()
    if tx == "214" and code == "M":
        raise ValueError("214 transaction uses M for minutes, not a convertible dimension")
    if tx == "210" and code == "PC":
        return "EA"
    return code


def _round_whole_positive(value: Decimal) -> Decimal:
    if value <= 0:
        return Decimal("0")
    if value < 1:
        return Decimal("1")
    return value.quantize(Decimal("1"), rounding=ROUND_HALF_UP)


def _normalize_weight(value: Decimal, factor: Decimal) -> NormalizedUnits:
    pounds = (value * factor).quantize(CENT, rounding=ROUND_HALF_UP)
    if pounds > 0 and pounds < 1:
        pounds = Decimal("1")
    if pounds > MAX_WEIGHT_LB:
        raise ValueError(f"weight {pounds} exceeds {MAX_WEIGHT_LB} lb")
    return NormalizedUnits(quantity=pounds, canonical_unit="LB")


def _normalize_dimension(value: Decimal, factor: Decimal) -> NormalizedUnits:
    inches = value * factor
    if inches > 0 and inches < 1:
        rounded = Decimal("1")
    else:
        rounded = inches.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    if rounded > MAX_DIMENSION_IN:
        raise ValueError(f"dimension {rounded} exceeds {MAX_DIMENSION_IN} in")
    return NormalizedUnits(quantity=rounded, canonical_unit="IN")


def _normalize_count(value: Decimal) -> NormalizedUnits:
    return NormalizedUnits(quantity=_round_whole_positive(value), canonical_unit="EA")


def normalize_edi_units(item: EDIQuantity) -> NormalizedUnits:
    """Convert one EDI quantity to Tidewater's canonical internal unit.

    >>> normalize_edi_units(EDIQuantity(Decimal("10"), "kg", "204"))
    NormalizedUnits(quantity=Decimal('22.05'), canonical_unit='LB')
    """
    if item.quantity < 0:
        raise ValueError("quantity cannot be negative")

    code = _effective_code(item)
    value = item.quantity

    if code in {"LB", "LBS"}:
        return _normalize_weight(value, Decimal("1"))
    if code == "KG":
        return _normalize_weight(value, KG_TO_LB)
    if code in {"IN", "INH"}:
        return _normalize_dimension(value, Decimal("1"))
    if code == "FT":
        return _normalize_dimension(value, FT_TO_IN)
    if code == "M":
        return _normalize_dimension(value, M_TO_IN)
    if code == "CM":
        return _normalize_dimension(value, CM_TO_IN)
    if code in {"EA", "CT", "PLT", "PC"}:
        return _normalize_count(value)

    raise ValueError(f"unsupported unit_code {code}")

bol_reference_parser.py:
"""Normalize bill-of-lading references from raw strings.

The settlement pipeline receives reference strings copied from shipper paperwork and EDI.
This parser extracts stable reference components so matching can ignore punctuation,
spacing, repeated labels, and scanner noise. Business rules:

- Empty tokens and tokens with no letters or digits are ignored.
- Known labels map to canonical prefixes: ``BOL``, ``PO``, ``SO``, and ``PU``.
- A token like ``BOL12345`` or ``PO-7788`` becomes one prefixed reference when the
  prefix is recognized and the remainder is valid.
- Numeric payloads drop leading zeros unless the whole value is zero. Alphanumeric
  payloads keep internal zeros.
- Payloads shorter than 3 characters are ignored, except ``PO`` allows 1 and ``PU``
  allows 1 because some customers use short order and pickup numbers.
- Payloads longer than 12 characters are ignored unless they are all digits, in which
  case the last 12 digits are kept; this handles overflowed scans.
- Duplicate normalized references are suppressed in first-seen order.
- A bare token with no recognizable prefix is treated as ``BOL`` only when it is all
  digits and has normalized length 3 to 10 inclusive.
"""

from dataclasses import dataclass

LABELS = {
    "BOL": "BOL",
    "BILL": "BOL",
    "BILL OF LADING": "BOL",
    "BILL-OF-LADING": "BOL",
    "PO": "PO",
    "P/O": "PO",
    "PURCHASE ORDER": "PO",
    "SO": "SO",
    "SHIPPER ORDER": "SO",
    "PU": "PU",
    "PICKUP": "PU",
}
MIN_LEN = {"BOL": 3, "PO": 1, "SO": 3, "PU": 1}
MAX_LEN = 12
SEPARATORS = " :-#/\\"


@dataclass(frozen=True)
class RawReferenceSet:
    references: tuple[str, ...]


@dataclass(frozen=True)
class ParsedReference:
    prefix: str
    value: str


def _clean(text: str) -> str:
    return " ".join(text.strip().upper().split())


def _payload_chars(text: str) -> str:
    return "".join(ch for ch in text if ch.isalnum())


def _normalize_value(prefix: str, value: str) -> str | None:
    raw = _payload_chars(value)
    if not raw:
        return None
    if raw.isdigit():
        raw = raw.lstrip("0") or "0"
    if len(raw) > MAX_LEN:
        if raw.isdigit():
            raw = raw[-MAX_LEN:]
        else:
            return None
    if len(raw) < MIN_LEN[prefix]:
        return None
    return raw


def _split_prefixed_token(token: str) -> tuple[str, str] | None:
    compact = _clean(token)
    for label, prefix in sorted(LABELS.items(), key=lambda item: len(item[0]), reverse=True):
        if compact == label:
            return None
        if compact.startswith(label):
            remainder = compact[len(label):].lstrip(SEPARATORS)
            if remainder:
                return prefix, remainder
    return None


def _extract_one(token: str, pending_prefix: str | None) -> tuple[ParsedReference | None, str | None]:
    cleaned = _clean(token)
    if not cleaned:
        return None, pending_prefix
    if cleaned in LABELS:
        return None, LABELS[cleaned]
    combined = _split_prefixed_token(cleaned)
    if combined is not None:
        prefix, remainder = combined
        value = _normalize_value(prefix, remainder)
        return (ParsedReference(prefix, value) if value else None), None
    if pending_prefix is not None:
        value = _normalize_value(pending_prefix, cleaned)
        return (ParsedReference(pending_prefix, value) if value else None), None
    raw = _payload_chars(cleaned)
    if raw.isdigit():
        normalized = raw.lstrip("0") or "0"
        if 3 <= len(normalized) <= 10:
            return ParsedReference("BOL", normalized), None
    return None, None


def parse_bol_references(raw: RawReferenceSet) -> tuple[ParsedReference, ...]:
    """Return unique normalized reference components in first-seen order."""
    seen: set[tuple[str, str]] = set()
    parsed: list[ParsedReference] = []
    pending_prefix: str | None = None
    for token in raw.references:
        item, pending_prefix = _extract_one(token, pending_prefix)
        if item is None:
            continue
        key = (item.prefix, item.value)
        if key in seen:
            continue
        seen.add(key)
        parsed.append(item)
    return tuple(parsed)

delivery_window.py:
"""Receiving windows at consignee facilities, and how an ETA sits against them.

Facilities publish receiving hours in their own local time, e.g. 08:00-16:00, or
22:00-06:00 for night receiving (the window closes the next morning). Dispatch
compares each truck's ETA, which routing computes in UTC, against the window to
decide whether to call ahead, re-sequence stops or book a new appointment.

All durations here are real elapsed time. A night window that spans the autumn
clock change is nine hours long, not eight.
"""

from dataclasses import dataclass
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

EARLY = "early"
ON_TIME = "on_time"
LATE = "late"


@dataclass(frozen=True)
class Window:
    opens: datetime  # aware, facility local time
    closes: datetime

    @property
    def zone(self) -> ZoneInfo:
        return self.opens.tzinfo


def receiving_window(day: date, open_at: time, close_at: time, facility_tz: str) -> Window:
    """The window that opens on ``day``; a close at or before the open is next day."""
    zone = ZoneInfo(facility_tz)
    opens = datetime.combine(day, open_at, tzinfo=zone)
    close_day = day + timedelta(days=1) if close_at <= open_at else day
    closes = datetime.combine(close_day, close_at, tzinfo=zone)
    return Window(opens, closes)


def _require_aware(moment: datetime) -> datetime:
    if moment.tzinfo is None:
        raise ValueError("ETA must be timezone-aware")
    return moment


def _elapsed_minutes(start: datetime, end: datetime) -> float:
    """Minutes from ``start`` to ``end``, measured in UTC."""
    return (end.astimezone(timezone.utc) - start.astimezone(timezone.utc)).total_seconds() / 60


def window_minutes(window: Window) -> float:
    return _elapsed_minutes(window.opens, window.closes)


def slack_minutes(eta: datetime, window: Window) -> float:
    """Minutes from the ETA until the window closes; negative means late."""
    local_eta = _require_aware(eta).astimezone(window.zone)
    return _elapsed_minutes(local_eta, window.closes)


def window_status(eta: datetime, window: Window) -> str:
    """EARLY before the window opens, LATE after it closes, else ON_TIME."""
    local_eta = _require_aware(eta).astimezone(window.zone)
    if _elapsed_minutes(window.opens, local_eta) < 0:
        return EARLY
    if slack_minutes(eta, window) < 0:
        return LATE
    return ON_TIME


def latest_departure(window: Window, drive_minutes: float) -> datetime:
    """The latest UTC departure from the previous stop that still makes the window."""
    return window.closes.astimezone(timezone.utc) - timedelta(minutes=drive_minutes)

invoice_dates.py:
"""Invoice and due dates for delivered loads, in the consignee's local time.

The nightly billing batch invoices every load delivered since the last run. Per
our customer contracts, a load's invoice date is the calendar date of delivery
where it was delivered (the consignee's time zone), not where we are and not UTC.
Due dates follow from the customer's net terms; one that lands on a weekend moves
to the following Monday.

Delivery timestamps come from the ELD/POD feed as aware UTC datetimes. Consignee
time zones are IANA names from the facility record ("America/New_York").
"""

from dataclasses import dataclass
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo

DEFAULT_TERMS_DAYS = 30


@dataclass(frozen=True)
class Delivery:
    load_id: str
    delivered_at: datetime
    consignee_tz: str
    terms_days: int = DEFAULT_TERMS_DAYS


@dataclass(frozen=True)
class InvoiceDates:
    invoice_date: date
    due_date: date


def _require_aware(moment: datetime, what: str) -> datetime:
    if moment.tzinfo is None or moment.utcoffset() is None:
        raise ValueError(f"{what} must be timezone-aware")
    return moment.astimezone(timezone.utc)


def _zones(deliveries: list[Delivery]) -> dict[str, ZoneInfo]:
    """Each consignee zone in the batch, loaded once."""
    return {name: ZoneInfo(name) for name in {d.consignee_tz for d in deliveries}}


def _local_delivery_date(delivered_at: datetime, zone: ZoneInfo) -> date:
    """The calendar date at the consignee when the load was delivered.

    The zone is applied at the delivery instant, so the date uses the UTC offset
    that was in force then (EDT or EST, PDT or PST).
    """
    return delivered_at.astimezone(zone).date()


def _roll_off_weekend(day: date) -> date:
    # Saturday -> Monday, Sunday -> Monday.
    if day.weekday() >= 5:
        return day + timedelta(days=7 - day.weekday())
    return day


def due_date(invoice_date: date, terms_days: int) -> date:
    if terms_days < 0:
        raise ValueError("terms_days must be non-negative")
    return _roll_off_weekend(invoice_date + timedelta(days=terms_days))


def invoice_dates_for_batch(deliveries: list[Delivery], run_at: datetime) -> dict[str, InvoiceDates]:
    """Invoice and due dates for every load delivered by ``run_at``.

    Loads delivered after ``run_at`` are left for the next run. All timestamps
    must be timezone-aware.
    """
    run_at = _require_aware(run_at, "run_at")
    zones = _zones(deliveries)
    dates = {}
    for delivery in deliveries:
        delivered_at = _require_aware(delivery.delivered_at, f"{delivery.load_id} delivered_at")
        if delivered_at > run_at:
            continue
        invoice_date = _local_delivery_date(delivered_at, zones[delivery.consignee_tz])
        dates[delivery.load_id] = InvoiceDates(invoice_date, due_date(invoice_date, delivery.terms_days))
    return dates

quick_pay.py:
"""Carrier quick pay.

Carriers are paid on 30-day terms from the day we approve their invoice. A carrier
can choose quick pay instead: we pay two business days after approval and keep a
fee from the payment. The fee is a percentage of the invoice with a floor. The
carrier payables job calls ``carrier_payment`` for every approved carrier invoice.
"""

from dataclasses import dataclass
from datetime import date, timedelta
from decimal import ROUND_HALF_UP, Decimal

QUICK_PAY_PERCENT = Decimal("3")
MINIMUM_FEE = Decimal("10.00")
STANDARD_TERMS = timedelta(days=30)
QUICK_PAY_BUSINESS_DAYS = 2
CENT = Decimal("0.01")


@dataclass(frozen=True)
class Payment:
    pay_date: date
    fee: Decimal
    net: Decimal


def quick_pay_fee(invoice_amount: Decimal) -> Decimal:
    fee = (invoice_amount * QUICK_PAY_PERCENT / 100).quantize(CENT, rounding=ROUND_HALF_UP)
    return max(fee, MINIMUM_FEE)


def _add_business_days(start: date, days: int) -> date:
    current = start
    while days:
        current += timedelta(days=1)
        if current.weekday() < 5:
            days -= 1
    return current


def carrier_payment(invoice_amount: Decimal, approved: date, quick_pay: bool) -> Payment:
    """When a carrier invoice is paid, the fee kept, and the amount sent."""
    if invoice_amount <= 0:
        raise ValueError(f"invoice amount must be positive, got {invoice_amount}")
    if not quick_pay:
        return Payment(approved + STANDARD_TERMS, Decimal("0.00"), invoice_amount)
    fee = quick_pay_fee(invoice_amount)
    return Payment(_add_business_days(approved, QUICK_PAY_BUSINESS_DAYS), fee, invoice_amount - fee)

residential_delivery_fee.py:
"""Residential delivery charges for shipments tendered to homes and similar non-commercial sites.

The billing service calls ``calculate_residential_delivery_fee`` once per shipment when
rating an accessorial. Standard Tidewater rules are:

* No residential fee applies when the destination is commercial.
* Parcel moves use weight breaks with a surcharge for oversized pieces.
* LTL moves use pallet and weight thresholds; very small dock-friendly drops get a
  reduced minimum fee.
* Remote residential destinations add a fixed tariff on top of the base fee.
* Contract customers may waive the fee entirely, receive a percent discount, or be
  subject to a per-shipment cap. Discounts apply before the cap.
* Charges are rounded half up to the cent, and oversized or remote surcharges are not
  assessed when the residential fee is fully waived.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
PARCEL_BASE_UNDER_70 = Decimal("4.50")
PARCEL_BASE_70_TO_150 = Decimal("8.00")
PARCEL_OVERSIZE_SURCHARGE = Decimal("12.50")
LTL_MINIMUM_FEE = Decimal("32.00")
LTL_SMALL_DROP_FEE = Decimal("18.00")
LTL_HEAVY_FEE = Decimal("48.00")
LTL_EXTRA_HEAVY_FEE = Decimal("72.00")
REMOTE_SURCHARGE = Decimal("9.75")


@dataclass(frozen=True)
class ShipmentFacts:
    destination_type: str
    mode: str
    billed_weight_lb: Decimal
    pieces: int = 1
    pallets: int = 0
    longest_side_in: int = 0
    remote_zip: bool = False
    liftgate_requested: bool = False


@dataclass(frozen=True)
class ResidentialTariff:
    residential_waived: bool = False
    discount_percent: Decimal = Decimal("0")
    shipment_cap: Decimal | None = None


def _validate(shipment: ShipmentFacts, tariff: ResidentialTariff) -> None:
    if shipment.destination_type not in {"residential", "commercial"}:
        raise ValueError("destination_type must be 'residential' or 'commercial'")
    if shipment.mode not in {"parcel", "ltl"}:
        raise ValueError("mode must be 'parcel' or 'ltl'")
    if shipment.billed_weight_lb < 0:
        raise ValueError("billed_weight_lb cannot be negative")
    if shipment.pieces < 1:
        raise ValueError("pieces must be at least 1")
    if shipment.pallets < 0:
        raise ValueError("pallets cannot be negative")
    if not (Decimal("0") <= tariff.discount_percent <= Decimal("100")):
        raise ValueError("discount_percent must be between 0 and 100")
    if tariff.shipment_cap is not None and tariff.shipment_cap < 0:
        raise ValueError("shipment_cap cannot be negative")


def _parcel_fee(shipment: ShipmentFacts) -> Decimal:
    if shipment.billed_weight_lb <= Decimal("70"):
        base = PARCEL_BASE_UNDER_70
    else:
        base = PARCEL_BASE_70_TO_150
    if shipment.longest_side_in > 48 or shipment.billed_weight_lb > Decimal("120"):
        base += PARCEL_OVERSIZE_SURCHARGE
    return base


def _ltl_fee(shipment: ShipmentFacts) -> Decimal:
    if (
        shipment.billed_weight_lb <= Decimal("150")
        and shipment.pallets == 0
        and not shipment.liftgate_requested
    ):
        return LTL_SMALL_DROP_FEE
    if shipment.billed_weight_lb > Decimal("1200") or shipment.pallets >= 4:
        return LTL_EXTRA_HEAVY_FEE
    if shipment.billed_weight_lb > Decimal("500") or shipment.pallets >= 2:
        return LTL_HEAVY_FEE
    return LTL_MINIMUM_FEE


def _apply_discount(amount: Decimal, discount_percent: Decimal) -> Decimal:
    if discount_percent == 0:
        return amount
    multiplier = (Decimal("100") - discount_percent) / Decimal("100")
    return amount * multiplier


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_residential_delivery_fee(
    shipment: ShipmentFacts, tariff: ResidentialTariff = ResidentialTariff()
) -> Decimal:
    """Residential delivery fee owed for one shipment.

    Residential fees apply only to residential destinations. Parcel thresholds are at
    70 lb and 120 lb, with an oversize trigger above 48 inches on the longest side.
    LTL thresholds are small-drop, heavy, and extra-heavy breaks. A remote zip code
    adds a fixed surcharge after the mode-based fee is determined. Contract discounts
    then apply, followed by any cap.
    """
    _validate(shipment, tariff)
    if shipment.destination_type == "commercial" or tariff.residential_waived:
        return Decimal("0.00")
    amount = _parcel_fee(shipment) if shipment.mode == "parcel" else _ltl_fee(shipment)
    if shipment.remote_zip:
        amount += REMOTE_SURCHARGE
    amount = _apply_discount(amount, tariff.discount_percent)
    amount = _apply_cap(amount, tariff.shipment_cap)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)

washout_fee.py:
"""Trailer washout reimbursement for contaminated equipment after delivery.

A washout is reimbursable only when the delivered commodity leaves the trailer needing
cleaning for the next load. The settlement service uses the rules below to decide how
much of a carrier-submitted wash receipt may be passed through to the customer.

Business rules:
- The required wash level is driven by the stronger of the commodity contamination
  class and the next-load requirement supplied by operations.
- Wash levels bill at contract maximums: rinse, standard, sanitize, and hazmat.
- Contracts may disallow pass-through entirely, or may disallow premium hazmat
  reimbursement even when a hazmat wash was operationally required.
- The reimbursable amount is the lesser of the actual receipt and the allowed maximum,
  reduced by any carrier deductible, then rounded to cents.
- Receipts at or below the deductible reimburse zero. Negative receipts and invalid
  combinations are rejected.
- Food-grade commodities require at least a sanitize wash.
- Non-contaminating dry freight does not reimburse unless operations explicitly require
  a wash for the next load.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

_LEVEL_ORDER = {"none": 0, "rinse": 1, "standard": 2, "sanitize": 3, "hazmat": 4}
_CLASS_MINIMUM = {
    "dry": "none",
    "produce": "rinse",
    "food": "sanitize",
    "chemical": "standard",
    "hazmat": "hazmat",
}
_MAX_BY_LEVEL = {
    "none": Decimal("0.00"),
    "rinse": Decimal("35.00"),
    "standard": Decimal("85.00"),
    "sanitize": Decimal("140.00"),
    "hazmat": Decimal("225.00"),
}


@dataclass(frozen=True)
class WashoutRequest:
    commodity_class: str
    required_wash_level: str
    receipt_amount: Decimal
    food_grade_trailer: bool = False


@dataclass(frozen=True)
class PassThroughTerms:
    allow_pass_through: bool = True
    allow_hazmat_premium: bool = True
    carrier_deductible: Decimal = Decimal("15.00")
    customer_cap: Decimal | None = None


def _validate(request: WashoutRequest, terms: PassThroughTerms) -> None:
    if request.commodity_class not in _CLASS_MINIMUM:
        raise ValueError(f"unknown commodity_class: {request.commodity_class}")
    if request.required_wash_level not in _LEVEL_ORDER:
        raise ValueError(f"unknown required_wash_level: {request.required_wash_level}")
    if request.receipt_amount < 0:
        raise ValueError("receipt_amount cannot be negative")
    if terms.carrier_deductible < 0:
        raise ValueError("carrier_deductible cannot be negative")
    if terms.customer_cap is not None and terms.customer_cap < 0:
        raise ValueError("customer_cap cannot be negative")


def _stronger_level(left: str, right: str) -> str:
    return left if _LEVEL_ORDER[left] >= _LEVEL_ORDER[right] else right


def _required_level(request: WashoutRequest) -> str:
    level = _stronger_level(_CLASS_MINIMUM[request.commodity_class], request.required_wash_level)
    if request.food_grade_trailer and _LEVEL_ORDER[level] < _LEVEL_ORDER["sanitize"]:
        return "sanitize"
    return level


def _allowed_maximum(level: str, terms: PassThroughTerms) -> Decimal:
    if not terms.allow_pass_through:
        return Decimal("0.00")
    if level == "hazmat" and not terms.allow_hazmat_premium:
        return _MAX_BY_LEVEL["standard"]
    return _MAX_BY_LEVEL[level]


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_washout_fee(
    request: WashoutRequest, terms: PassThroughTerms = PassThroughTerms()
) -> Decimal:
    """Reimbursable washout amount in dollars, rounded to the cent.

    The payable amount is limited by the required wash level, contract settings,
    optional customer cap, and the carrier deductible.
    """
    _validate(request, terms)
    level = _required_level(request)
    if level == "none":
        return Decimal("0.00")

    allowed = _allowed_maximum(level, terms)
    allowed = _apply_cap(allowed, terms.customer_cap)
    eligible = min(request.receipt_amount, allowed)
    if eligible <= terms.carrier_deductible:
        return Decimal("0.00")

    reimbursable = eligible - terms.carrier_deductible
    return reimbursable.quantize(CENT, rounding=ROUND_HALF_UP)

